window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-bf191fbb35032f36"]={"versions": [{"id": "FIG-bf191fbb35032f36", "releases": ["R20-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Aktivitätsdiagramm zur Spezifikation des Kontrollflusses der Funktion <code>E2E_P07mCheck</code> (Server-Overload-Variante) innerhalb der AUTOSAR-E2E-Bibliothek (End-to-End Communication Protection, Profile 7m).</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\"><li>Funktionsschnittstelle: <code>E2E_P07mCheck(Config, State, SourceID, MessageTyp, MessageResult, Data, Length)</code> (im Diagrammkopf abgeschnitten dargestellt als <code>E2E_P07mCheck(Config, State, SourceID, MessageTyp, MessageResult, Data,</code>)\n</li><li>Unteraktivitäten / Call-Behavior-Aktionen (mit Refinement-Symbol):\n<ul class=\"fig-list\"><li><code>Verify inputs of the check function</code>\n</li><li><code>Compute offset</code>\n</li><li><code>Read Length</code>\n</li><li><code>Read Counter</code>\n</li><li><code>Read DataID</code>\n</li><li><code>Read SourceID</code>\n</li><li><code>Read Message Type</code>\n</li><li><code>Read Message Result</code>\n</li><li><code>Read CRC</code>\n</li><li><code>Compute CRC</code>\n</li><li><code>Do checks</code>\n</li></ul>\n</li><li>Entscheidungsknoten (Decision Node): Verzweigung nach Bedingung <code>NewDataAvailable == TRUE</code> mit den Guards <code>[TRUE]</code> und <code>[FALSE]</code>\n</li><li>Kontrollfluss-Verzweigungen bei Eingabeprüfung: Guards <code>[input ok]</code>, <code>[null input]</code> und <code>[wrong input]</code>\n</li><li>Ablaufendknoten (Activity Final Nodes): Drei Endknoten mit Rückgaben (<code>return</code>), korrespondierend zu den Fehlerpfaden und dem regulären Prüfpfad.\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ol class=\"fig-list\"><li>Start am Initialknoten beim Aufruf von <code>E2E_P07mCheck</code>.\n</li><li>Ausführung der Eingabevalidierung in <code>Verify inputs of the check function</code>.\n</li><li>Verzweigung anhand des Validierungsergebnisses:\n<ul class=\"fig-list\"><li>Bei <code>[null input]</code>: Direkter Übergang zum linken Endknoten (Rückgabe des Fehlers für Null-Pointer).\n</li><li>Bei <code>[wrong input]</code>: Direkter Übergang zum rechten Endknoten (Rückgabe des Fehlers für ungültige Parameter).\n</li><li>Bei <code>[input ok]</code>: Übergang zur Auswertung der Bedingung <code>NewDataAvailable == TRUE</code>.\n</li></ul>\n</li><li>Entscheidung an der Bedingung <code>NewDataAvailable == TRUE</code>:\n<ul class=\"fig-list\"><li>Zweig <code>[TRUE]</code>: Sequenzielle Abarbeitung der Schritte:\n<ul class=\"fig-list\"><li><code>Compute offset</code>\n</li><li><code>Read Length</code>\n</li><li><code>Read Counter</code>\n</li><li><code>Read DataID</code>\n</li><li><code>Read SourceID</code>\n</li><li><code>Read Message Type</code>\n</li><li><code>Read Message Result</code>\n</li><li><code>Read CRC</code>\n</li><li><code>Compute CRC</code>\n</li><li>Anschließend Übergang zu <code>Do checks</code>.\n</li></ul>\n</li><li>Zweig <code>[FALSE]</code>: Umgehung der Lese- und CRC-Berechnungsschritte über einen Bypass direkt zu <code>Do checks</code>.\n</li></ul>\n</li><li>Ausführung von <code>Do checks</code> und abschließender Übergang zum mittleren Endknoten (<code>return</code>).\n</li></ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Normative Spezifikation des Gesamtverhaltens der Server-Overload-Funktion <code>E2E_P07mCheck()</code> gemäß <code>[PRS_E2E_00841]</code>.</p>\n<p class=\"fig-p\">Entwickler-Hinweise zur Implementierung:</p>\n<ul class=\"fig-list\"><li>Streng deterministische Fehlerabfangung: Vor jeder Datenverarbeitung müssen Parameter auf Nullzeiger (<code>[null input]</code>) und Wertebereichsgrenzen (<code>[wrong input]</code>) geprüft werden; bei Fehlern bricht die Funktion sofort ohne Zustands- oder Datenveränderung ab.\n</li><li>Wenn keine neuen Daten anliegen (<code>NewDataAvailable == FALSE</code>), werden weder Header-Felder extrahiert noch CRCs gerechnet, sondern direkt die E2E-Zustandsprüfungen (<code>Do checks</code>) ausgeführt.\n</li><li>Bei Vorliegen neuer Daten (<code>NewDataAvailable == TRUE</code>) ist die Extraktion der Profil-7m-spezifischen Header-Felder (Länge, Counter, DataID, SourceID, Message Type, Message Result, CRC) sowie die CRC-Prüfsummenberechnung vor der finalen Bewertung zwingend vorgeschrieben.\n</li></ul>"}, {"id": "FIG-32b9a7324c30dae4", "releases": ["R21-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Aktivitätsdiagramm zur Spezifikation des Kontrollflusses der Funktion <code>E2E_P07mCheck</code> (Server-Overload-Variante) innerhalb der AUTOSAR-E2E-Bibliothek (End-to-End Communication Protection, Profile 7m).</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\"><li>Funktionsschnittstelle: <code>E2E_P07mCheck(Config, State, SourceID, MessageTyp, MessageResult, Data, Length)</code> (im Diagrammkopf abgeschnitten dargestellt als <code>E2E_P07mCheck(Config, State, SourceID, MessageTyp, MessageResult, Data,</code>)\n</li><li>Unteraktivitäten / Call-Behavior-Aktionen (mit Refinement-Symbol):\n<ul class=\"fig-list\"><li><code>Verify inputs of the check function</code>\n</li><li><code>Compute offset</code>\n</li><li><code>Read Length</code>\n</li><li><code>Read Counter</code>\n</li><li><code>Read DataID</code>\n</li><li><code>Read SourceID</code>\n</li><li><code>Read Message Type</code>\n</li><li><code>Read Message Result</code>\n</li><li><code>Read CRC</code>\n</li><li><code>Compute CRC</code>\n</li><li><code>Do checks</code>\n</li></ul>\n</li><li>Entscheidungsknoten (Decision Node): Verzweigung nach Bedingung <code>NewDataAvailable == TRUE</code> mit den Guards <code>[TRUE]</code> und <code>[FALSE]</code>\n</li><li>Kontrollfluss-Verzweigungen bei Eingabeprüfung: Guards <code>[input ok]</code>, <code>[null input]</code> und <code>[wrong input]</code>\n</li><li>Ablaufendknoten (Activity Final Nodes): Drei Endknoten mit Rückgaben (<code>return</code>), korrespondierend zu den Fehlerpfaden und dem regulären Prüfpfad.\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ol class=\"fig-list\"><li>Start am Initialknoten beim Aufruf von <code>E2E_P07mCheck</code>.\n</li><li>Ausführung der Eingabevalidierung in <code>Verify inputs of the check function</code>.\n</li><li>Verzweigung anhand des Validierungsergebnisses:\n<ul class=\"fig-list\"><li>Bei <code>[null input]</code>: Direkter Übergang zum linken Endknoten (Rückgabe des Fehlers für Null-Pointer).\n</li><li>Bei <code>[wrong input]</code>: Direkter Übergang zum rechten Endknoten (Rückgabe des Fehlers für ungültige Parameter).\n</li><li>Bei <code>[input ok]</code>: Übergang zur Auswertung der Bedingung <code>NewDataAvailable == TRUE</code>.\n</li></ul>\n</li><li>Entscheidung an der Bedingung <code>NewDataAvailable == TRUE</code>:\n<ul class=\"fig-list\"><li>Zweig <code>[TRUE]</code>: Sequenzielle Abarbeitung der Schritte:\n<ul class=\"fig-list\"><li><code>Compute offset</code>\n</li><li><code>Read Length</code>\n</li><li><code>Read Counter</code>\n</li><li><code>Read DataID</code>\n</li><li><code>Read SourceID</code>\n</li><li><code>Read Message Type</code>\n</li><li><code>Read Message Result</code>\n</li><li><code>Read CRC</code>\n</li><li><code>Compute CRC</code>\n</li><li>Anschließend Übergang zu <code>Do checks</code>.\n</li></ul>\n</li><li>Zweig <code>[FALSE]</code>: Umgehung der Lese- und CRC-Berechnungsschritte über einen Bypass direkt zu <code>Do checks</code>.\n</li></ul>\n</li><li>Ausführung von <code>Do checks</code> und abschließender Übergang zum mittleren Endknoten (<code>return</code>).\n</li></ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Normative Spezifikation des Gesamtverhaltens der Server-Overload-Funktion <code>E2E_P07mCheck()</code> gemäß <code>[PRS_E2E_00841]</code>.</p>\n<p class=\"fig-p\">Entwickler-Hinweise zur Implementierung:</p>\n<ul class=\"fig-list\"><li>Streng deterministische Fehlerabfangung: Vor jeder Datenverarbeitung müssen Parameter auf Nullzeiger (<code>[null input]</code>) und Wertebereichsgrenzen (<code>[wrong input]</code>) geprüft werden; bei Fehlern bricht die Funktion sofort ohne Zustands- oder Datenveränderung ab.\n</li><li>Wenn keine neuen Daten anliegen (<code>NewDataAvailable == FALSE</code>), werden weder Header-Felder extrahiert noch CRCs gerechnet, sondern direkt die E2E-Zustandsprüfungen (<code>Do checks</code>) ausgeführt.\n</li><li>Bei Vorliegen neuer Daten (<code>NewDataAvailable == TRUE</code>) ist die Extraktion der Profil-7m-spezifischen Header-Felder (Länge, Counter, DataID, SourceID, Message Type, Message Result, CRC) sowie die CRC-Prüfsummenberechnung vor der finalen Bewertung zwingend vorgeschrieben.\n</li></ul>"}], "trans": [{"from": "FIG-bf191fbb35032f36", "to": "FIG-32b9a7324c30dae4", "fr": "R20-11", "tr": "R21-11", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}]};
